// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }

    function testFuzz_property(address actor) public {
        // any address may attempt to call DrugDealer; the contract decides admissibility
        vm.assume(actor != address(this));
        vm.prank(actor);
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a successful DrugDealer call always leaves ceoAddress equal to the
        // (nonzero) caller; a failing call must revert. ceoAddress is never address(0).
        assertTrue(!ok || (c.ceoAddress() == actor && c.ceoAddress() != address(0)));
    }
}
